-- Non-owner public-RPC assertions; parent rolls all synthetic rows back.
do $$declare w uuid:=current_setting('eps.casting.fixture.workspace')::uuid;s uuid:=current_setting('eps.casting.fixture.slot')::uuid;s2 uuid:=current_setting('eps.casting.fixture.slot2')::uuid;p uuid:=current_setting('eps.casting.fixture.pool')::uuid;p2 uuid:=current_setting('eps.casting.fixture.pool2')::uuid;
 a jsonb;b jsonb;c jsonb;body jsonb;result jsonb;undo_value jsonb;list_value jsonb;cursor_value text;current_v bigint;ctx jsonb;begin
 body:=jsonb_build_object('slot_id',s,'workspace_candidate_id',p,'expected_slot_row_version',1);a:=public.eps_create_assignment(w,body,'m04-create-first');
 if a->>'position'<>'option'or(a->>'shortlist_included')::boolean or a->'slide_wording'<>'{}'::jsonb then raise exception'M04_DEFAULT_OPTION_FAILED';end if;
 if public.eps_create_assignment(w,body,'m04-create-first')<>a then raise exception'M04_CREATE_EXACT_REPLAY_FAILED';end if;
 begin perform public.eps_create_assignment(w,body||'{"shortlist_included":true}','m04-create-first');raise exception'EXPECTED_IDEMPOTENCY_KEY_REUSED';exception when sqlstate'P0001'then if sqlerrm<>'IDEMPOTENCY_KEY_REUSED'then raise;end if;end;
 body:=body||'{"expected_slot_row_version":2,"shortlist_included":true}';if public.eps_create_assignment(w,body,'m04-existing-no-reset')<>a then raise exception'M04_EXISTING_MUST_NOT_RESET_OR_INCLUDE';end if;
 ctx:=public.eps_get_casting_context('assignment',(a->>'id')::uuid);if ctx->>'workspace_id'<>w::text or ctx->>'slot_id'<>s::text then raise exception'M04_CONTEXT_SCOPE_FAILED';end if;
 begin perform public.eps_create_assignment(w,jsonb_build_object('slot_id','8a4a0000-0000-4000-8000-000000000003','workspace_candidate_id',p,'expected_slot_row_version',1),'m04-foreign-slot');raise exception'EXPECTED_RESOURCE_NOT_FOUND';exception when sqlstate'P0001'then if sqlerrm<>'RESOURCE_NOT_FOUND'then raise;end if;end;
 b:=public.eps_create_assignment(w,jsonb_build_object('slot_id',s,'workspace_candidate_id',p2,'expected_slot_row_version',2),'m04-create-second');
 c:=public.eps_create_assignment(w,jsonb_build_object('slot_id',s2,'workspace_candidate_id',p,'expected_slot_row_version',1,'shortlist_included',true),'m04-two-roles');
 a:=public.eps_update_assignment((a->>'id')::uuid,jsonb_build_object('row_version',1,'shortlist_included',true,'presentation_notes','Synthetic public note','internal_notes','Synthetic private note','slide_wording','{"age_or_range":"Presentation wording only"}'::jsonb),'m04-local-edits');
 if a->>'row_version'<>'2'or a->'slide_wording'->>'age_or_range'<>'Presentation wording only'then raise exception'M04_LOCAL_EDIT_FAILED';end if;
 a:=public.eps_update_assignment((a->>'id')::uuid,'{"row_version":2,"slide_wording":{"age_or_range":null}}','m04-wording-inherit');if a->'slide_wording'?'age_or_range'then raise exception'M04_NULL_MUST_REMOVE_OVERRIDE';end if;
 list_value:=public.eps_list_assignments(w,'selection',null,1);cursor_value:=list_value->'page'->>'next_cursor';if jsonb_array_length(list_value->'data')<>1 or cursor_value is null then raise exception'M04_ORDERED_PAGE_FAILED';end if;
 if jsonb_array_length(public.eps_list_assignments(w,'shortlist',null,100)->'data')<>2 then raise exception'M04_EXPLICIT_SHORTLIST_FAILED';end if;
 begin perform public.eps_list_assignments(w,'shortlist',cursor_value,1);raise exception'EXPECTED_FILTER_CURSOR_REJECTION';exception when sqlstate'P0001'then if sqlerrm<>'VALIDATION_FAILED'then raise;end if;end;
 body:=jsonb_build_object('assignment_id',a->'id','expected_slot_row_version',3,'replacement_behavior','move_previous_to_backup');result:=public.eps_set_slot_main(s,body,'m04-main-first');undo_value:=result->'undo';if result->'slot'->>'row_version'<>'4'then raise exception'M04_MAIN_SLOT_VERSION_FAILED';end if;
 if public.eps_set_slot_main(s,body,'m04-main-first')<>result then raise exception'M04_MAIN_REPLAY_FAILED';end if;
 begin perform public.eps_list_assignments(w,'selection',cursor_value,1);raise exception'EXPECTED_STALE_CURSOR';exception when sqlstate'P0001'then if sqlerrm<>'STALE_RESOURCE_VERSION'then raise;end if;end;
 begin perform public.eps_update_assignment((a->>'id')::uuid,'{"row_version":4,"position":"backup"}','m04-main-direct-denied');raise exception'EXPECTED_MAIN_OPERATION_REQUIRED';exception when sqlstate'P0001'then if sqlerrm<>'MAIN_OPERATION_REQUIRED'then raise;end if;end;
 begin perform public.eps_undo_slot_main(s,jsonb_set(undo_value,'{restore_assignment_positions,0,position}','"backup"'),'m04-forged-undo');raise exception'EXPECTED_MAIN_UNDO_INVALID';exception when sqlstate'P0001'then if sqlerrm<>'MAIN_UNDO_INVALID'then raise;end if;end;
 result:=public.eps_undo_slot_main(s,undo_value,'m04-valid-undo');if result->'undo'<>'null'::jsonb or result->'affected_assignments'->0->>'position'<>'option'then raise exception'M04_EXACT_INVERSE_FAILED';end if;
 if public.eps_undo_slot_main(s,undo_value,'m04-valid-undo')<>result then raise exception'M04_UNDO_REPLAY_AFTER_CONSUMPTION_FAILED';end if;
 begin perform public.eps_undo_slot_main(s,undo_value,'m04-second-undo-key');raise exception'EXPECTED_MAIN_UNDO_ALREADY_USED';exception when sqlstate'P0001'then if sqlerrm<>'MAIN_UNDO_ALREADY_USED'then raise;end if;end;
 result:=public.eps_set_slot_main(s,jsonb_build_object('assignment_id',a->'id','expected_slot_row_version',5,'replacement_behavior','move_previous_to_backup'),'m04-main-again');undo_value:=result->'undo';
 a:=public.eps_update_assignment((a->>'id')::uuid,'{"row_version":6,"internal_notes":"Changed after Main"}','m04-stale-undo-note');
 begin perform public.eps_undo_slot_main(s,undo_value,'m04-stale-undo');raise exception'EXPECTED_STALE_NOTE_INVERSE';exception when sqlstate'P0001'then if sqlerrm<>'MAIN_UNDO_INVALID'then raise;end if;end;
 result:=public.eps_set_slot_main(s,jsonb_build_object('assignment_id',b->'id','expected_slot_row_version',6,'replacement_behavior','move_previous_to_backup'),'m04-main-replacement');if jsonb_array_length(result->'affected_assignments')<>2 then raise exception'M04_REPLACE_MUST_AFFECT_BOTH';end if;
 result:=public.eps_set_slot_main(s,'{"assignment_id":null,"expected_slot_row_version":7,"replacement_behavior":"move_previous_to_backup"}','m04-main-clear');if result->'affected_assignments'->0->>'position'<>'backup'then raise exception'M04_CLEAR_MUST_DEMOTE_BACKUP';end if;
 perform public.eps_remove_assignment((c->>'id')::uuid,jsonb_build_object('row_version',1,'reason','Remove only second role'),'m04-remove-one-role');
 if public.eps_remove_assignment((c->>'id')::uuid,jsonb_build_object('row_version',1,'reason','Remove only second role'),'m04-remove-one-role')<>jsonb_build_object('success',true,'affected_ids',jsonb_build_array(c->'id'))then raise exception'M04_REMOVE_REPLAY_FAILED';end if;
 if jsonb_array_length(public.eps_list_assignments(w,'selection',null,100)->'data')<>2 then raise exception'M04_REMOVAL_MUST_RETAIN_OTHER_ROLE';end if;
 perform set_config('eps.casting.fixture.assignment',a->>'id',true);perform set_config('eps.casting.fixture.assignment2',b->>'id',true);
end$$;
