 perform set_config('request.jwt.claim.sub',current_setting('eps.casting.fixture.actor2'),true);perform set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('eps.casting.fixture.actor2'),'role','authenticated')::text,true);
