do $$declare w uuid:=current_setting('eps.casting.fixture.workspace')::uuid;a uuid:=current_setting('eps.casting.fixture.assignment')::uuid;begin
 if(select count(*)from eps.assignments where slot_id=current_setting('eps.casting.fixture.slot')::uuid and archived_at is null and position='main')<>0 then raise exception'M04_CLEAR_INVARIANT_FAILED';end if;
 if(select facts->>'age_or_range'from eps.candidates where id='8a5a0000-0000-4000-8000-000000000001')is not null then raise exception'M04_FACTS_MUST_REMAIN_UNCHANGED';end if;
 if(select count(*)from eps.assignment_change_consumptions)<>2 then raise exception'M04_CONSUMPTION_MUST_BE_ONE_SHOT';end if;
 if not eps.casting_has_active_assignments(w)or eps.casting_has_active_assignments(current_setting('eps.casting.fixture.workspace2')::uuid)then raise exception'M04_SCOPED_SERVICE_GUARD_FAILED';end if;
 begin insert into eps.assignments(workspace_id,slot_id,workspace_candidate_id)values(current_setting('eps.casting.fixture.workspace2')::uuid,current_setting('eps.casting.fixture.slot')::uuid,'8a6a0000-0000-4000-8000-000000000003');raise exception'EXPECTED_COMPOSITE_FK';exception when foreign_key_violation then null;end;
 update eps.assignments set position='main'where id=a;
